// ---- API client ----
// Set to a deployed backend's URL (see dalab-backend.zip) to switch this
// dashboard from demo/mock data to the real API. Empty by default — every
// section below keeps working exactly as it does now off the initial* mock
// arrays. Once set, Overview and Orders (the two sections wired below) pull
// real data instead; the same DalabAdminApi.request pattern extends to the
// remaining sections mechanically (each is currently local useState seeded
// from an initial* constant — swap that seed for a DalabAdminApi call the
// same way Overview/Orders do here).
const DALAB_API_BASE_URL = import.meta.env.VITE_API_BASE_URL || "";
const DALAB_API_ENABLED = Boolean(DALAB_API_BASE_URL);

let dalabAdminAccessToken = null;

async function dalabAdminApiRequest(path, { method = "GET", body } = {}) {
  if (!DALAB_API_ENABLED) throw new Error("DALAB API not configured (DALAB_API_BASE_URL is empty)");
  const headers = { "Content-Type": "application/json" };
  if (dalabAdminAccessToken) headers.Authorization = `Bearer ${dalabAdminAccessToken}`;
  const controller = new AbortController();
  // Render's free-tier backend can take 30-60s to wake from an idle cold
  // start, so a much shorter timeout would misfire on a legitimate first
  // request of the day — but without any timeout, a genuine network/backend
  // hang left every caller (e.g. a "Saving..." button) waiting forever with
  // zero feedback, which is the exact bug this closes.
  const timeoutId = setTimeout(() => controller.abort(), 45000);
  let res;
  try {
    res = await fetch(`${DALAB_API_BASE_URL}${path}`, {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
  } catch (err) {
    if (err.name === "AbortError") {
      throw new Error("Request timed out — the server may be waking up after being idle. Please try again in a moment.");
    }
    throw new Error("Could not reach the server. Check your connection and try again.");
  } finally {
    clearTimeout(timeoutId);
  }
  const json = await res.json().catch(() => null);
  if (!res.ok) throw new Error(json?.error || `Request failed (${res.status})`);
  return json;
}

