// Normalizes a GET /admin/companies row into the shape every section of this
// app already expects (color/group/status/payNumber, established by the
// original mock data) so the live company list is a drop-in replacement —
// no other component needs to know field names changed.
function normalizeCompany(c) {
  return {
    id: c.id,
    name: c.name,
    group: c.groupNumber,
    color: c.colorHex || "#1D2E8C",
    status: c.status === "online" ? "enabled" : "disabled",
    payNumber: c.paymentNumber || "Not set",
    paymentUssdTemplate: c.paymentUssdTemplate || "",
    gateway: c.gateway || "Manual",
    visibleCustomerApp: c.visibleCustomerApp !== false,
    visibleAgentApp: c.visibleAgentApp !== false,
    autoProcessEnabled: c.autoProcessEnabled !== false,
    slug: c.slug || "",
    description: c.description || "",
    sortOrder: c.sortOrder ?? 0,
    hasLogo: Boolean(c.hasLogo),
  };
}

// Same idea for GET /admin/customers — the mock shape has `points`/`joined`,
// the live API returns `macaashPoints`/`createdAt`; it also has no per-
// customer order count (a separate, more expensive query), so that field is
// left undefined rather than faked as zero.
function normalizeCustomer(c) {
  return {
    id: c.id,
    name: c.name,
    phone: c.phone,
    status: c.status,
    points: c.macaashPoints ?? 0,
    joined: c.createdAt ? new Date(c.createdAt).toLocaleDateString() : "",
    pinSet: c.pinSet ?? false,
  };
}

// A regular Admin only has whatever the Super Admin has explicitly granted
// (see admin_users.permissions[] / requirePermission() server-side); the
// Super Admin always passes without consulting the array.
function hasPermission(admin, key) {
  if (!admin) return false;
  if (admin.role === "super_admin") return true;
  return Array.isArray(admin.permissions) && admin.permissions.includes(key);
}

// Browser EventSource can't attach an Authorization header, so real-time
// order sync uses fetch()'s streaming body instead, parsing the same
// `data: {...}\n\n` framing the Agent App's OkHttp SSE client consumes.
// Reconnects with exponential backoff on any drop; the caller decides what
// "disconnected" means for its own UI (e.g. Orders falls back to polling).
function subscribeOrderEvents(path, { onEvent, onOpen, onClose } = {}) {
  let stopped = false;
  let controller = null;
  let retryDelayMs = 2000;
  let retryTimer = null;

  async function connectOnce() {
    if (stopped || !DALAB_API_ENABLED) return;
    controller = new AbortController();
    try {
      const res = await fetch(`${DALAB_API_BASE_URL}${path}`, {
        headers: {
          Accept: "text/event-stream",
          ...(dalabAdminAccessToken ? { Authorization: `Bearer ${dalabAdminAccessToken}` } : {}),
        },
        signal: controller.signal,
      });
      if (!res.ok || !res.body) throw new Error(`SSE connection failed (${res.status})`);
      retryDelayMs = 2000;
      onOpen?.();

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      while (!stopped) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const frames = buffer.split("\n\n");
        buffer = frames.pop() ?? "";
        for (const frame of frames) {
          const dataLine = frame.split("\n").find((l) => l.startsWith("data:"));
          if (dataLine) onEvent?.(dataLine.slice(5).trim());
        }
      }
    } catch (err) {
      if (stopped || err.name === "AbortError") return;
    }
    onClose?.();
    if (!stopped) {
      retryTimer = setTimeout(connectOnce, retryDelayMs);
      retryDelayMs = Math.min(retryDelayMs * 2, 30000);
    }
  }

  connectOnce();
  return () => {
    stopped = true;
    controller?.abort();
    if (retryTimer) clearTimeout(retryTimer);
  };
}

/**
 * System-health panel shown persistently across every dashboard section
 * (mounted once in AdminDashboardShell) — this is deliberately its own SSE
 * subscription rather than reusing Orders'/ExecutionLogs' per-view ones, so
 * it keeps reporting real connection health even while the admin is looking
 * at a section (e.g. Settings) that has no live stream of its own.
 */
function useConnectionStatus() {
  const [sseState, setSseState] = useState("connecting"); // connecting | connected | disconnected
  const [dbState, setDbState] = useState("checking"); // checking | connected | unreachable
  const [eventCount, setEventCount] = useState(0);
  const [lastSyncAt, setLastSyncAt] = useState(null);

  useEffect(() => {
    if (!DALAB_API_ENABLED) return;
    const unsubscribe = subscribeOrderEvents("/admin/orders/stream", {
      onEvent: () => { setEventCount((n) => n + 1); setLastSyncAt(new Date()); },
      onOpen: () => setSseState("connected"),
      onClose: () => setSseState((prev) => (prev === "connecting" ? "connecting" : "disconnected")),
    });
    return unsubscribe;
  }, []);

  useEffect(() => {
    if (!DALAB_API_ENABLED) return;
    let cancelled = false;
    const checkHealth = async () => {
      try {
        const res = await fetch(`${DALAB_API_BASE_URL}/health`);
        if (cancelled) return;
        if (res.ok) {
          setDbState("connected");
          setLastSyncAt(new Date());
        } else {
          setDbState("unreachable");
        }
      } catch {
        if (!cancelled) setDbState("unreachable");
      }
    };
    checkHealth();
    const interval = setInterval(checkHealth, 15000);
    return () => { cancelled = true; clearInterval(interval); };
  }, []);

  return { sseState, dbState, eventCount, lastSyncAt };
}

function ConnectionStatusBar() {
  const { sseState, dbState, eventCount, lastSyncAt } = useConnectionStatus();

  if (!DALAB_API_ENABLED) return null;

  const sseTone = sseState === "connected" ? GREEN : sseState === "connecting" ? "#A9720A" : "#C81E2C";
  const sseLabel = sseState === "connected" ? "Connected" : sseState === "connecting" ? "Reconnecting…" : "Disconnected";
  const dbTone = dbState === "connected" ? GREEN : dbState === "checking" ? "#A9720A" : "#C81E2C";
  const dbLabel = dbState === "connected" ? "Session active" : dbState === "checking" ? "Checking…" : "Unreachable";
  const overallLive = sseState === "connected" && dbState === "connected";

  const Item = ({ icon: Icon, label, value, tone }) => (
    <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "0 16px", borderRight: `1px solid ${BORDER}` }}>
      <Icon size={14} color={tone || MUTE} />
      <div>
        <div style={{ fontSize: 10, color: MUTE, fontWeight: 700, letterSpacing: 0.3 }}>{label}</div>
        <div style={{ fontSize: 12, fontWeight: 700, color: tone || INK }}>{value}</div>
      </div>
    </div>
  );

  return (
    <div style={{
      display: "flex", alignItems: "stretch", flexWrap: "wrap", background: "#fff", borderBottom: `1px solid ${BORDER}`,
      padding: "8px 10px 8px 0",
    }}>
      <Item icon={Radio} label="SSE LIVE STREAM" value={sseLabel} tone={sseTone} />
      <Item icon={Database} label="DATABASE SESSION" value={dbLabel} tone={dbTone} />
      <Item icon={Activity} label="SYNC STATUS" value={`${eventCount} update${eventCount === 1 ? "" : "s"} received`} tone={overallLive ? GREEN : undefined} />
      <Item icon={overallLive ? Wifi : WifiOff} label="LIVE UPDATES" value={overallLive ? "Receiving" : "Paused"} tone={overallLive ? GREEN : "#A9720A"} />
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "0 16px" }}>
        <Clock3 size={14} color={MUTE} />
        <div>
          <div style={{ fontSize: 10, color: MUTE, fontWeight: 700, letterSpacing: 0.3 }}>LAST SYNC TIME</div>
          <div style={{ fontSize: 12, fontWeight: 700, color: INK }}>{lastSyncAt ? lastSyncAt.toLocaleTimeString() : "—"}</div>
        </div>
      </div>
    </div>
  );
}

